#!/bin/bash
set -euo pipefail

unresolved_file=$(mktemp)
trap 'rm -f "$unresolved_file"' EXIT

awk -v output="/home/eval/app/app.conf" -v unresolved="$unresolved_file" '
FILENAME == ARGV[1] {
    if ($0 == "" || substr($0, 1, 1) == "#")
        next
    pos = index($0, "=")
    if (pos > 0)
        values[substr($0, 1, pos - 1)] = substr($0, pos + 1)
    next
}
{
    rest = $0
    rendered = ""
    while (match(rest, /\$\{[A-Za-z_][A-Za-z0-9_]*\}/)) {
        placeholder = substr(rest, RSTART, RLENGTH)
        name = substr(placeholder, 3, length(placeholder) - 3)
        rendered = rendered substr(rest, 1, RSTART - 1)
        if (name in values)
            rendered = rendered values[name]
        else {
            rendered = rendered placeholder
            missing[name] = 1
        }
        rest = substr(rest, RSTART + RLENGTH)
    }
    print rendered rest > output
}
END {
    for (name in missing)
        print name > unresolved
}
' /home/eval/app/prod.env /home/eval/app/app.conf.tmpl

names=$(LC_ALL=C sort -u "$unresolved_file" | paste -sd ' ' -)
printf 'unresolved: %s\n' "$names"
exit 0
